@push('scripts')<script>
function showTarget(){const v=$('#targetType').val();$('.target').addClass('d-none');if(v==='users')$('.target-users').removeClass('d-none');if(v==='department')$('.target-department').removeClass('d-none');if(v==='position')$('.target-position').removeClass('d-none')}
$('#targetType').on('change',showTarget);showTarget();
$('#bulkForm').on('submit',function(e){e.preventDefault();$('#bulkError,#bulkSuccess').addClass('d-none');$.ajax({url:'{{ route('tasks.bulk.store') }}',method:'POST',data:$(this).serialize()}).done(r=>{$('#bulkSuccess').removeClass('d-none').html(`<b>Готово.</b> Создано задач: ${r.created}. <a href="{{ route('tasks.page') }}">Открыть список задач</a>`)}).fail(x=>{$('#bulkError').removeClass('d-none').text(x.responseJSON?.message||'Ошибка массовой постановки')})});
</script>@endpush
